/** 
 * Should be called whenever a service reaches a terminal state ( {@linkplain State#TERMINATED terminated} or {@linkplain State#FAILED failed}).
 */
@GuardedBy("monitor") private void serviceStopped(Service service){
  checkState(unstoppedServices > 0,"All services should have already stopped but %s just stopped.",service);
  unstoppedServices--;
  if (unstoppedServices == 0) {
    checkState(unstartedServices == 0,"All services are stopped but %d services haven't finished starting",unstartedServices);
    try {
      for (final ListenerExecutorPair pair : listeners) {
        queuedListeners.add(new Runnable(){
          @Override public void run(){
            pair.listener.stopped();
          }
        }, pair.executor);
      }
      listeners.clear();
    } catch (NullPointerException e) {
      // Handle the case where runnable or executor is null
      e.printStackTrace();
    } catch (UnsupportedOperationException e) {
      // Handle the case where listeners.clear() is not supported
      e.printStackTrace();
    }
  }
}
